 void EditSymbol(int index){int item=-3-index;bool existing=index<=-3&&item>=0&&item<symbols.Count;if(!existing&&symbols.Count>=20){Error(new Exception(Loc.T("Najviac 20 symbolov.")));return;}var symbol=existing?symbols[item].Copy():new SymbolItem();using(var dialog=new Form{Text=symbol.Name,Size=new Size(530,390),StartPosition=FormStartPosition.CenterParent,Font=Font,ShowInTaskbar=false,MinimizeBox=false,MaximizeBox=false}){
