  if(dialog.ShowDialog(this)!=DialogResult.OK)return;symbol.X=(double)values[0].Value*unitFactor;symbol.Y=(double)values[1].Value*unitFactor;symbol.Width=(double)values[2].Value*unitFactor;symbol.Height=(double)values[3].Value*unitFactor;if(existing)symbols[item]=symbol;else{symbols.Add(symbol);item=symbols.Count-1;}Changed(this,EventArgs.Empty);timer.Stop();UpdatePreview();preview.SelectElement(-3-item);
 }}
